def parse_day(html: str, day: dt.date) -> list[dict[str, Any]]:
    """Extract the top-200 rows of one historical snapshot page."""
    soup = BeautifulSoup(html, "lxml")

    # The page contains several <table>s; the snapshot data lives in the one
    # whose <tbody> holds the cmc-table-row elements.
    table = tbody = None
    for cand in soup.find_all("table"):
        tb = cand.find("tbody")
        if tb is not None and tb.find("tr", class_="cmc-table-row") is not None:
            table, tbody = cand, tb
            break
    if table is None or tbody is None:
        l.warning("%s: no snapshot table found in page", day)
        return []

    # Map column index -> field using the sort-by__* class on each header cell.
    col_map: dict[int, str] = {}
    thead = table.find("thead")
    if thead:
        for i, th in enumerate(thead.find_all("th")):
            for cls in th.get("class", []):
                if cls.startswith("cmc-table__cell--sort-by__"):
                    field = SORT_FIELDS.get(cls.rsplit("__", 1)[1])
                    if field is not None:
                        col_map[i] = field

    rows: list[dict[str, Any]] = []

    for tr in tbody.find_all("tr"):
        classes = tr.get("class", [])
        if "cmc-table-row" not in classes:
            continue
        rec = {name: None for name in SCHEMA}
        rec["date"] = day
        tds = tr.find_all("td")
        for idx, field in col_map.items():
            if idx >= len(tds):
                continue
            cell = tds[idx]
            if field == "name":
                # Cell holds an icon plus symbol and name anchors; take those
                # so we don't get the concatenated "BTCBitcoin" text.
                sym_a = cell.select_one("a.cmc-table__column-name--symbol")
                name_a = cell.select_one("a.cmc-table__column-name--name")
                if sym_a is not None and name_a is not None:
                    rec["symbol"] = sym_a.get_text(strip=True)
                    rec["name"] = name_a.get_text(strip=True)
                    slug = (name_a.get("href") or "").rstrip("/").split("/")[-1]
                    rec["slug"] = slug or None
                else:
                    rec["name"] = cell.get_text(" ", strip=True)
            elif field == "symbol":
                # Only fall back to this column if the name cell lacked anchors.
                if rec["symbol"] is None:
                    rec["symbol"] = cell.get_text(strip=True)
            elif field == "rank":
                rec["rank"] = parse_num(cell.get_text(strip=True))
            else:
                rec[field] = parse_num(cell.get_text(strip=True))
        rows.append(rec)


